def build_data():
    from marketplace import CONFIG,HOTELS,service_labels
    from hanoi_hotels import HOTELS as HANOI_HOTELS
    from world_destinations import COUNTRIES,city_name
    from world_guides import COPY as GUIDES
    from home_tools import forecast_points
    from world_weather import TIMEZONES
    from datetime import datetime,timezone
    settings=json.loads((ROOT/'data/assistant_config.json').read_text())
    if settings.get('analytics_retention_days')!=7:raise ValueError('Backend retention policy is fixed at seven days')
    endpoint=settings['backend_url']
    if endpoint:
        p=urlsplit(endpoint)
        if p.scheme!='https' or not p.hostname or p.username or p.password or p.query or p.fragment or p.path not in ('','/') or p.port:raise ValueError('Backend URL must be a HTTPS origin without credentials')
    forecasts=json.loads((ROOT/'data/weather.json').read_text())['cities']
    data={'base':BASE,'backendUrl':endpoint.rstrip('/'),'retentionDays':7,'services':CONFIG['services'],'hotels':[{'slug':h['slug'],'name':h['name'] if h['display_name']=='Da Nang' else h['display_name'],'url':h['url']} for h in HOTELS]+[{'slug':h['slug'],'name':h['name'],'url':h['urls'][0],'city':'hanoi'} for h in HANOI_HOTELS],'cities':{city[0]:{'name':city[1],'country':country[2],'region':country[0],'aliases':sorted({city_name(city,lang) for lang in UI})} for country in COUNTRIES for city in country[4]},'weather':{key:{'timezone':TIMEZONES[key],'updated':value.get('source_updated_at'),'points':forecast_points(value,datetime.now(timezone.utc))} for key,value in forecasts.items()},'locales':{lang:{'ui':ui,'services':service_labels(lang),'guide':GUIDES[lang][3],'booking':GUIDES[lang][8],'weather':GUIDES[lang][5],'weatherTitle':GUIDES[lang][4],'planningTitle':GUIDES[lang][2]} for lang,ui in UI.items()}}
    (ROOT/'assets/chatbot-data.json').write_text(json.dumps(data,ensure_ascii=False,separators=(',',':'))+'\n',encoding='utf-8')
def widget(lang,current,relative):
    u=UI[lang]
    return f'''<div class="travel-chat" data-chat-data="{relative(current,'assets/chatbot-data.json')}"><button type="button" class="chat-open" aria-label="{E(u[0])}" title="{E(u[0])}" aria-controls="travel-chat-dialog" aria-haspopup="dialog"><svg width="25" height="25" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 4h14a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2h-9l-5 3v-3a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Z" fill="none" stroke="currentColor" stroke-width="1.8"/><path d="M7 9h10M7 13h7" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg><span class="sr-only">{E(u[0])}</span></button><dialog id="travel-chat-dialog" class="chat-dialog" aria-labelledby="travel-chat-title"><div class="chat-header"><h2 id="travel-chat-title">{E(u[1])}</h2><button type="button" class="chat-close" aria-label="{E(u[2])}">×</button></div><p class="chat-mode">{E(u[5])}</p><div class="chat-messages" role="log" aria-live="polite"></div><div class="chat-questions"></div><form class="chat-form"><label class="sr-only" for="travel-chat-input">{E(u[3])}</label><input id="travel-chat-input" name="question" autocomplete="off" maxlength="600" required placeholder="{E(u[3])}"><button type="submit">{E(u[4])}</button></form></dialog></div>'''
def stats(lang):
    u=UI[lang]
    return f'''<section class="visitor-statistics" aria-labelledby="visitor-stats-title"><h3 id="visitor-stats-title">{E(u[10])}</h3><p class="visitor-count">{E(u[11])}</p><div class="analytics-consent" hidden><p>{E(u[12])}</p><button type="button" data-analytics-consent="yes">{E(u[13])}</button> <button type="button" data-analytics-consent="no">{E(u[14])}</button></div><button class="analytics-revoke" type="button" hidden>{E(u[20])}</button><details class="analytics-admin"><summary>{E(u[15])}</summary><form class="analytics-admin-form"><label>{E(u[16])}<input type="password" name="token" autocomplete="off" required minlength="32"></label><button type="submit">{E(u[17])}</button></form><p class="analytics-status" role="status"></p><div class="analytics-results"></div></details></section>'''
